from google.cloud import translate_v3
import os

class TranslationClient:
    def __init__(self, project_id: str = None):
        self.client = translate_v3.TranslationServiceClient()
        self.project_id = project_id if project_id else os.getenv("GOOGLE_CLOUD_PROJECT")
        if not self.project_id:
            raise ValueError("Google Cloud Project ID not provided and GOOGLE_CLOUD_PROJECT environment variable not set.")
        self.parent = f"projects/{self.project_id}"

    def translate_text(self, text: str, target_language_code: str, source_language_code: str = None) -> str:
        request = {
            "parent": self.parent,
            "contents": [text],
            "target_language_code": target_language_code,
        }
        if source_language_code:
            request["source_language_code"] = source_language_code

        response = self.client.translate_text(request=request)
        return response.translations[0].translated_text

from google.cloud import translate_v3 as translate
from bs4 import BeautifulSoup

def translate_html_markup(html_content: str, source_language: str, target_language: str) -> str:
    client = translate.TranslationServiceClient()
    parent = f"projects/your-project-id"  # Replace with your Google Cloud Project ID

    soup = BeautifulSoup(html_content, 'html.parser')

    for text_node in soup.find_all(string=True):
        if text_node.strip():  # Only translate non-empty text
            response = client.translate_text(
                request={
                    "parent": parent,
                    "contents": [text_node.strip()],
                    "mime_type": "text/html",
                    "source_language_code": source_language,
                    "target_language_code": target_language,
                }
            )
            translated_text = response.translations[0].translated_text
            text_node.replace_with(translated_text)

    return str(soup)
